window.CODE = Object.assign(window.CODE || {}, {"ch11/confidence.py":"\"\"\"Know when to hand over: rules first, then the model's own confidence, then a person.\n\nThe model's self-reported confidence is a useful signal, not a guarantee. Hard rules\n(emergency words, write actions) always win over it.\n\nRun:  python confidence.py\n\"\"\"\nimport json\nimport re\nimport sys\nfrom pathlib import Path\n\nsys.path.insert(0, str(Path(__file__).resolve().parent.parent))\nfrom llm import chat  # noqa: E402\n\nEMERGENCY = re.compile(r\"chest pain|can'?t breathe|breathless|unconscious|not waking|bleeding heavily|stroke|seizure\", re.I)\nTHRESHOLD = 0.7\nINFO = \"OPD: Mon-Sat 9-1 and 4-7. Dr Rao cardiology Thu/Fri. PM-JAY accepted. Emergency 24h, call 108.\"\n\n\ndef answer_with_confidence(question: str) -> dict:\n    # 1. Hard rules first: no model judgement needed, no model call wasted.\n    if EMERGENCY.search(question):\n        return {\"route\": \"emergency\", \"reply\": \"Please go to Emergency now or call 108. A nurse is being alerted.\",\n                \"confidence\": None, \"reason\": \"emergency keywords\"}\n    raw = chat(f\"Clinic information: {INFO}\\nPatient: {question}\\n\\n\"\n               \"Answer only from the clinic information. Reply with JSON only: \"\n               '{\"reply\": \"...\", \"confidence\": 0.0-1.0, \"missing\": \"what you would need to be sure, or empty\"}',\n               temperature=0, max_tokens=250)[\"text\"]\n    try:\n        r = json.loads(raw.strip().removeprefix(\"```json\").removesuffix(\"```\"))\n    except json.JSONDecodeError:\n        r = {\"reply\": \"\", \"confidence\": 0.0, \"missing\": \"invalid model output\"}\n    # 2. Low confidence or missing information: a person takes over, with the draft attached.\n    if r.get(\"confidence\", 0) < THRESHOLD or r.get(\"missing\"):\n        return {\"route\": \"human\", \"reply\": \"Let me connect you with our front desk to be sure.\",\n                \"confidence\": r.get(\"confidence\"), \"reason\": r.get(\"missing\") or \"low confidence\", \"draft\": r.get(\"reply\")}\n    return {\"route\": \"auto\", \"reply\": r[\"reply\"], \"confidence\": r[\"confidence\"], \"reason\": \"\"}\n\n\nif __name__ == \"__main__\":\n    for q in [\"Is OPD open on Saturday evening?\",\n              \"Does my company insurance cover a knee MRI?\",\n              \"My father is breathless and very drowsy\"]:\n        r = answer_with_confidence(q)\n        print(f\"{r['route']:<9} conf={r['confidence']}  {q}\\n          -> {r['reply']}  {('(' + r['reason'] + ')') if r['reason'] else ''}\")\n","ch11/plan_execute.py":"\"\"\"Plan-and-execute with replanning, and ReWOO, using the Chapter 9 clinic tools.\n\nplan_and_execute  1 call to plan -> run each step -> if a step fails, replan with what we know -> answer\nrewoo             1 call to plan with placeholders (#E1, #E2) -> run ALL tools with no model calls\n                  in between -> 1 call to write the answer. Fewest model calls, but cannot adapt mid-way.\n\nRun:  python plan_execute.py\n\"\"\"\nimport json\nimport sys\nfrom pathlib import Path\n\nHERE = Path(__file__).resolve().parent\nsys.path.insert(0, str(HERE.parent))\nsys.path.insert(0, str(HERE.parent / \"ch09\"))\nfrom clinic import TOOL_DOCS, run_tool  # noqa: E402\nfrom llm import chat  # noqa: E402\n\nTOOLS_TEXT = \"\\n\".join(f\"- {t['name']}({', '.join(t['parameters']['properties'])}): {t['description']}\" for t in TOOL_DOCS)\n\n\ndef ask_json(prompt: str) -> list | dict:\n    raw = chat(prompt, temperature=0, max_tokens=500)[\"text\"]\n    return json.loads(raw.strip().removeprefix(\"```json\").removesuffix(\"```\"))\n\n\ndef plan(task: str, done: list | None = None) -> list[dict]:\n    history = f\"\\nSteps already done and their results:\\n{json.dumps(done)}\\nPlan only the REMAINING steps.\" if done else \"\"\n    return ask_json(f\"Task: {task}\\n\\nAvailable tools:\\n{TOOLS_TEXT}{history}\\n\\n\"\n                    'Reply with a JSON list of steps only: [{\"tool\": \"...\", \"args\": {...}, \"why\": \"...\"}]. '\n                    \"Use as few steps as possible. Reply [] if no more tools are needed.\")\n\n\ndef plan_and_execute(task: str, max_replans: int = 2) -> dict:\n    calls, done = 0, []\n    steps = plan(task); calls += 1\n    replans = 0\n    while steps:\n        step = steps.pop(0)\n        result = run_tool(step[\"tool\"], step[\"args\"])\n        done.append({\"tool\": step[\"tool\"], \"args\": step[\"args\"], \"result\": result})\n        print(f\"  ran {step['tool']}({step['args']}) -> {result}\")\n        if \"error\" in result and replans < max_replans:     # the plan met reality: replan\n            print(\"  step failed -> replanning\")\n            steps = plan(task, done); calls += 1; replans += 1\n    answer = chat(f\"Task: {task}\\nResults: {json.dumps(done)}\\nWrite the short final reply to the patient. \"\n                  \"Requests are pending staff approval, not confirmed.\", temperature=0, max_tokens=200)[\"text\"]\n    return {\"answer\": answer, \"model_calls\": calls + 1, \"steps\": len(done)}\n\n\ndef rewoo(task: str) -> dict:\n    steps = ask_json(f\"Task: {task}\\n\\nAvailable tools:\\n{TOOLS_TEXT}\\n\\n\"\n                     \"Plan ALL tool calls up front. Name each result #E1, #E2, ... and use those names in later \"\n                     'args if needed. JSON list only: [{\"id\": \"#E1\", \"tool\": \"...\", \"args\": {...}}]')\n    evidence = {}\n    for s in steps:                                           # no model calls in this loop\n        args = {k: (json.dumps(evidence[v]) if isinstance(v, str) and v in evidence else v) for k, v in s[\"args\"].items()}\n        evidence[s[\"id\"]] = run_tool(s[\"tool\"], args)\n        print(f\"  {s['id']} = {s['tool']}({args}) -> {evidence[s['id']]}\")\n    answer = chat(f\"Task: {task}\\nEvidence: {json.dumps(evidence)}\\nWrite the short final reply to the patient. \"\n                  \"Requests are pending staff approval, not confirmed.\", temperature=0, max_tokens=200)[\"text\"]\n    return {\"answer\": answer, \"model_calls\": 2, \"steps\": len(steps)}\n\n\nif __name__ == \"__main__\":\n    task = \"Patient Asha Verma wants the earliest orthopaedics doctor on Wednesday; if none, request the next available day.\"\n    print(\"PLAN-AND-EXECUTE\")\n    r = plan_and_execute(task)\n    print(f\"-> {r['answer']}\\n   ({r['model_calls']} model calls, {r['steps']} tool steps)\\n\")\n    print(\"REWOO\")\n    r = rewoo(\"Tell the patient which days Dr Rao and Dr Iyer each work.\")\n    print(f\"-> {r['answer']}\\n   ({r['model_calls']} model calls, {r['steps']} tool steps)\")\n","ch11/reflection.py":"\"\"\"Reflection: generate a draft, critique it against a rubric, revise until it passes.\n\nRun:  python reflection.py\n\"\"\"\nimport json\nimport sys\nfrom pathlib import Path\n\nsys.path.insert(0, str(Path(__file__).resolve().parent.parent))\nfrom llm import chat  # noqa: E402\n\nRUBRIC = \"\"\"1. Answers the patient's actual question.\n2. Gives no medical advice (no medicines, doses or diagnoses).\n3. For any possible emergency symptom, tells them to go to Emergency or call 108 first.\n4. Under 80 words, polite, plain English.\n5. States only facts present in the provided information.\"\"\"\n\nINFO = \"Dr Rao (cardiology) sees OPD patients Thursday and Friday. Emergency is open 24 hours; call 108.\"\n\n\ndef draft(question: str) -> str:\n    return chat(f\"Clinic information: {INFO}\\n\\nPatient: {question}\\n\\nWrite the helpdesk reply.\",\n                system=\"You are the City Clinic helpdesk.\", temperature=0.4, max_tokens=200)[\"text\"]\n\n\ndef critique(question: str, reply: str) -> dict:\n    raw = chat(f\"Rubric:\\n{RUBRIC}\\n\\nClinic information: {INFO}\\nPatient: {question}\\nReply: {reply}\\n\\n\"\n               'Check the reply against every rubric point. Answer with JSON only: '\n               '{\"pass\": true/false, \"problems\": [\"...\"]}', temperature=0, max_tokens=200)[\"text\"]\n    try:\n        return json.loads(raw.strip().removeprefix(\"```json\").removesuffix(\"```\"))\n    except json.JSONDecodeError:\n        return {\"pass\": False, \"problems\": [\"Critic reply was not valid JSON\"]}\n\n\ndef revise(question: str, reply: str, problems: list[str]) -> str:\n    return chat(f\"Clinic information: {INFO}\\nPatient: {question}\\nYour draft: {reply}\\n\\n\"\n                \"Fix these problems and return only the improved reply:\\n- \" + \"\\n- \".join(problems),\n                system=\"You are the City Clinic helpdesk.\", temperature=0, max_tokens=200)[\"text\"]\n\n\ndef reflect(question: str, max_rounds: int = 2) -> dict:\n    reply, calls = draft(question), 1\n    for round_ in range(1, max_rounds + 1):\n        verdict = critique(question, reply)\n        calls += 1\n        print(f\"round {round_}: pass={verdict.get('pass')} problems={verdict.get('problems')}\")\n        if verdict.get(\"pass\"):\n            break\n        reply = revise(question, reply, verdict.get(\"problems\", []))\n        calls += 1\n    return {\"reply\": reply, \"model_calls\": calls}\n\n\nif __name__ == \"__main__\":\n    r = reflect(\"I've had chest pain since morning. Should I take a Disprin and wait for Dr Rao on Thursday?\")\n    print(f\"\\nFinal ({r['model_calls']} model calls):\\n{r['reply']}\")\n","common/llm.py":"\"\"\"One small helper so every chapter can call OpenAI or Anthropic the same way.\n\nChoose the provider in .env:   PROVIDER=openai   or   PROVIDER=anthropic\nOverride models if you like:   OPENAI_MODEL=...  ANTHROPIC_MODEL=...\n\n    from llm import chat, stream, achat\n    reply = chat(\"What are OPD timings?\", system=\"You are the City Clinic helpdesk.\")\n    print(reply[\"text\"], reply[\"input_tokens\"], reply[\"output_tokens\"])\n\"\"\"\nimport os\n\nfrom dotenv import load_dotenv\n\nload_dotenv()\nPROVIDER = os.getenv(\"PROVIDER\", \"openai\")\nMODELS = {\"openai\": os.getenv(\"OPENAI_MODEL\", \"gpt-4.1-mini\"),\n          \"anthropic\": os.getenv(\"ANTHROPIC_MODEL\", \"claude-haiku-5-5\")}\nTIMEOUT = float(os.getenv(\"LLM_TIMEOUT\", \"30\"))   # seconds per request; the SDK default is minutes\nRETRIES = int(os.getenv(\"LLM_RETRIES\", \"2\"))       # the SDKs retry rate limits and server errors for you\n_clients = {}\n\n\ndef _client(provider: str, use_async: bool = False):\n    key = (provider, use_async)\n    if key not in _clients:\n        if provider == \"openai\":\n            import openai\n            cls = openai.AsyncOpenAI if use_async else openai.OpenAI\n            _clients[key] = cls(timeout=TIMEOUT, max_retries=RETRIES)\n        else:\n            import anthropic\n            cls = anthropic.AsyncAnthropic if use_async else anthropic.Anthropic\n            _clients[key] = cls(timeout=TIMEOUT, max_retries=RETRIES)\n    return _clients[key]\n\n\ndef _openai_messages(user, system, history):\n    msgs = [{\"role\": \"system\", \"content\": system}] if system else []\n    return msgs + list(history or []) + [{\"role\": \"user\", \"content\": user}]\n\n\ndef _anthropic_args(user, system, history, temperature, max_tokens, model):\n    args = {\"model\": model, \"max_tokens\": max_tokens,\n            \"messages\": list(history or []) + [{\"role\": \"user\", \"content\": user}]}\n    if system:\n        args[\"system\"] = system\n    # `temperature` is accepted so both providers share one call shape, but it is NOT sent to Anthropic: the\n    # current anthropic SDK (1.x and later) raises TypeError if you pass it. OpenAI still honours it.\n    return args\n\n\ndef chat(user: str, system: str | None = None, history: list | None = None,\n         temperature: float | None = None, max_tokens: int = 800, provider: str | None = None) -> dict:\n    \"\"\"Send one message (plus optional earlier history). Returns text and token counts.\"\"\"\n    provider = provider or PROVIDER\n    model = MODELS[provider]\n    if provider == \"openai\":\n        kwargs = {\"model\": model, \"messages\": _openai_messages(user, system, history), \"max_completion_tokens\": max_tokens}\n        if temperature is not None:\n            kwargs[\"temperature\"] = temperature\n        r = _client(provider).chat.completions.create(**kwargs)\n        return {\"text\": r.choices[0].message.content, \"input_tokens\": r.usage.prompt_tokens,\n                \"output_tokens\": r.usage.completion_tokens, \"model\": model}\n    r = _client(provider).messages.create(**_anthropic_args(user, system, history, temperature, max_tokens, model))\n    return {\"text\": \"\".join(b.text for b in r.content if b.type == \"text\"), \"input_tokens\": r.usage.input_tokens,\n            \"output_tokens\": r.usage.output_tokens, \"model\": model}\n\n\ndef stream(user: str, system: str | None = None, history: list | None = None,\n           max_tokens: int = 800, provider: str | None = None):\n    \"\"\"Yield the reply a few words at a time, as the model writes it.\"\"\"\n    provider = provider or PROVIDER\n    model = MODELS[provider]\n    if provider == \"openai\":\n        chunks = _client(provider).chat.completions.create(\n            model=model, messages=_openai_messages(user, system, history), max_completion_tokens=max_tokens, stream=True)\n        for chunk in chunks:\n            if chunk.choices and chunk.choices[0].delta.content:\n                yield chunk.choices[0].delta.content\n    else:\n        with _client(provider).messages.stream(**_anthropic_args(user, system, history, None, max_tokens, model)) as s:\n            yield from s.text_stream\n\n\nasync def achat(user: str, system: str | None = None, temperature: float | None = None,\n                max_tokens: int = 800, provider: str | None = None) -> dict:\n    \"\"\"Async version of chat(), for running many calls at the same time (Chapter 4).\"\"\"\n    provider = provider or PROVIDER\n    model = MODELS[provider]\n    if provider == \"openai\":\n        kwargs = {\"model\": model, \"messages\": _openai_messages(user, system, None), \"max_completion_tokens\": max_tokens}\n        if temperature is not None:\n            kwargs[\"temperature\"] = temperature\n        r = await _client(provider, use_async=True).chat.completions.create(**kwargs)\n        return {\"text\": r.choices[0].message.content, \"input_tokens\": r.usage.prompt_tokens,\n                \"output_tokens\": r.usage.completion_tokens, \"model\": model}\n    r = await _client(provider, use_async=True).messages.create(\n        **_anthropic_args(user, system, None, temperature, max_tokens, model))\n    return {\"text\": \"\".join(b.text for b in r.content if b.type == \"text\"), \"input_tokens\": r.usage.input_tokens,\n            \"output_tokens\": r.usage.output_tokens, \"model\": model}\n\n\n# ---------------------------------------------------------------- embeddings (Chapter 6 onwards)\n# Anthropic does not offer its own embedding model, so embeddings come from OpenAI or from a\n# free local model. Choose in .env:  EMBEDDINGS=openai  (default)  or  EMBEDDINGS=local\nEMBEDDINGS = os.getenv(\"EMBEDDINGS\", \"openai\")\nEMBED_MODELS = {\"openai\": os.getenv(\"OPENAI_EMBED_MODEL\", \"text-embedding-3-small\"),\n                \"local\": os.getenv(\"LOCAL_EMBED_MODEL\", \"all-MiniLM-L6-v2\")}\n\n\ndef embed(texts: list[str], kind: str | None = None) -> list[list[float]]:\n    \"\"\"Turn each text into a vector of numbers that represents its meaning.\"\"\"\n    kind = kind or EMBEDDINGS\n    if kind == \"openai\":\n        r = _client(\"openai\").embeddings.create(model=EMBED_MODELS[\"openai\"], input=texts)\n        return [d.embedding for d in r.data]\n    if \"local\" not in _clients:                     # pip install sentence-transformers (downloads ~90 MB once)\n        from sentence_transformers import SentenceTransformer\n        _clients[\"local\"] = SentenceTransformer(EMBED_MODELS[\"local\"])\n    return _clients[\"local\"].encode(texts, normalize_embeddings=True).tolist()\n","common/requirements.txt":"# Pinned versions the course code was tested with. Install with: pip install -r requirements.txt\nopenai==3.43.0\nanthropic==2.4.0\npython-dotenv>=1.0\npydantic==2.13.5\ntiktoken>=0.8            # Chapter 2\nfastapi==0.162.0         # Chapter 5\nuvicorn>=0.30\npython-multipart>=0.0.9\nhttpx>=0.27\nstreamlit==1.66.1\ngradio==6.31.0\npytest>=8\n\n# Part C: frameworks and protocols (tested versions)\nlangchain==1.4.8                 # Chapters 12-13\nlangchain-core==1.7.4\nlangchain-openai==1.7.3\nlangchain-anthropic==1.7.9\nlangchain-community==0.4.2\nlangchain-text-splitters==1.1.3\nlangchain-classic==1.0.8         # only for legacy examples (AgentExecutor, old retrievers)\nlanggraph==1.2.19                # Chapters 14-15\nlanggraph-checkpoint-sqlite==3.1.3\nmcp==1.30.0                      # Chapters 16-17\nlangchain-mcp-adapters==0.3.2\nnetworkx==3.7                    # Chapter 18 (GraphRAG)\nchromadb==1.5.9                  # Chapters 6, 18, 19\nagno==3.1.12                     # Chapter 19\n# Optional: langchain-tavily, wikipedia, langchain-experimental (Chapter 13 built-in tools)\n# DSPy (Chapter 20) goes in a separate environment: see ch20/requirements-dspy.txt\n\n# Part D: multi-agent\n# CrewAI (Chapter 24) and AutoGen (Chapter 25) need their own environments: ch24/requirements-crewai.txt, ch25/requirements-autogen.txt\na2a-sdk==1.3.0                   # Chapter 26 (agent interoperability)\nfastapi==0.162.0\nuvicorn==0.54.0\n"});
